    if ((temperature == NULL) || (voltage == NULL) || (resistance == NULL) ||
        (next_temperature == NULL) || (current == NULL) || (power == NULL) || (total_power == NULL)) {
        return ADCS_E_NULL;
    }

    for (int i = 0; i < 3; i++) {
        if (!isfinite(voltage[i]) || !isfinite(resistance[i]) || !isfinite(temperature[i])) {
            return ADCS_E_RANGE;
        }
        if (resistance[i] <= 0.0) {
            return ADCS_E_RANGE;
        }
    }

    if (!isfinite(ambient) || !isfinite(thermal_capacity) || !isfinite(thermal_resistance) ||
        !isfinite(dt) || thermal_capacity <= 0.0 || thermal_resistance <= 0.0 || dt < 0.0) {
        return ADCS_E_RANGE;
    }

    double total_power_sum = 0.0;

    // Axis X
    {
        double v = voltage->x;
        double r = resistance->x;
        double t = temperature->x;
        double i_curr = v / r;
        double p_joule = v * i_curr;

        current->x = i_curr;
        power->x = p_joule;
        next_temperature->x = t + dt * (p_joule - (t - ambient) / thermal_resistance) / thermal_capacity;

        total_power_sum += p_joule;
    }

    // Axis Y
    {
        double v = voltage->y;
        double r = resistance->y;
        double t = temperature->y;
        double i_curr = v / r;
        double p_joule = v * i_curr;

        current->y = i_curr;
        power->y = p_joule;
        next_temperature->y = t + dt * (p_joule - (t - ambient) / thermal_resistance) / thermal_capacity;

        total_power_sum += p_joule;
    }

    // Axis Z
    {
        double v = voltage->z;
        double r = resistance->z;
        double t = temperature->z;
        double i_curr = v / r;
        double p_joule = v * i_curr;

        current->z = i_curr;
        power->z = p_joule;
        next_temperature->z = t + dt * (p_joule - (t - ambient) / thermal_resistance) / thermal_capacity;

        total_power_sum += p_joule;
    }

    *total_power = total_power_sum;

    return ADCS_OK;
}

