    double p[3];
    adcs_vec3_t c;

    // Axis X
    c.x = voltage->x / resistance->x;
    p[0] = voltage->x * voltage->x / resistance->x;

    // Axis Y
    c.y = voltage->y / resistance->y;
    p[1] = voltage->y * voltage->y / resistance->y;

    // Axis Z
    c.z = voltage->z / resistance->z;
    p[2] = voltage->z * voltage->z / resistance->z;

    *current = c;
    *power = (adcs_vec3_t){p[0], p[1], p[2]};

    *total_power = p[0] + p[1] + p[2];

    double inv_thermal_cap = 1.0 / thermal_capacity;
    double inv_thermal_res = 1.0 / thermal_resistance;

    // Update Temperature X
    next_temperature->x = temperature->x + dt * (p[0] - (temperature->x - ambient) * inv_thermal_res) * inv_thermal_cap;

    // Update Temperature Y
    next_temperature->y = temperature->y + dt * (p[1] - (temperature->y - ambient) * inv_thermal_res) * inv_thermal_cap;

    // Update Temperature Z
