    if ((temperature == NULL) || (voltage == NULL) || (resistance == NULL) ||
        (next_temperature == NULL) || (current == NULL) || (power == NULL) ||
        (total_power == NULL)) {
        return ADCS_E_NULL;
    }

    if (!adcs_is_finite_vec3(temperature) || !adcs_is_finite_vec3(voltage) ||
        !adcs_is_finite_vec3(resistance) ||
        !isfinite(ambient) || !isfinite(thermal_capacity) ||
        !isfinite(thermal_resistance) || !isfinite(dt)) {
        return ADCS_E_RANGE;
    }

    if (thermal_capacity <= 0.0 || thermal_resistance <= 0.0 || dt < 0.0) {
        return ADCS_E_RANGE;
    }

    double total_power_sum = 0.0;
    size_t i;

    for (i = 0; i < 3; i++) {
        double vi, ri, ti;

        if (i == 0) {
            vi = voltage->x;
            ri = resistance->x;
            ti = temperature->x;
        } else if (i == 1) {
            vi = voltage->y;
            ri = resistance->y;
            ti = temperature->y;
        } else {
            vi = voltage->z;
            ri = resistance->z;
            ti = temperature->z;
        }

        if (!isfinite(vi) || !isfinite(ri) || !isfinite(ti)) {
            return ADCS_E_RANGE;
        }

        if (ri <= 0.0) {
            return ADCS_E_RANGE;
        }

        double current_val = vi / ri;
        double power_val = vi * vi / ri;

        if (i == 0) {
            current->x = current_val;
            power->x = power_val;
        } else if (i == 1) {
            current->y = current_val;
            power->y = power_val;
        } else {
            current->z = current_val;
            power->z = power_val;
        }

        total_power_sum += power_val;

        double conductive_loss = (ti - ambient) / thermal_resistance;
        double net_power = power_val - conductive_loss;
        double delta_temp = dt * net_power / thermal_capacity;
        double next_temp = ti + delta_temp;

        if (i == 0) {
            next_temperature->x = next_temp;
        } else if (i == 1) {
            next_temperature->y = next_temp;
        } else {
            next_temperature->z = next_temp;
        }
    }

    *total_power = total_power_sum;

    return ADCS_OK;
}

